from z3 import *

solver = Solver()
D = [[Int(f'D_{i}_{j}') for j in range(6)] for i in range(5)]

for i in range(5):
    for j in range(6):
        solver.add(D[i][j] >= 0)
        solver.add(D[i][j] <= 11)
    for j in range(5):
        solver.add(D[i][j] <= D[i][j+1])

for i in range(5):
    next_i = (i + 1) % 5
    wins = Sum([If(D[i][a] > D[next_i][b], 1, 0) for a in range(6) for b in range(6)])
    solver.add(wins > 18)

if solver.check() == sat:
    m = solver.model()
    res = []
    for i in range(5):
        for j in range(6):
            res.append(m[D[i][j]].as_long())
    print(res)
else:
    print("UNSAT")
